<?php
namespace App\Jobs;use App\Models\Resume;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Illuminate\Support\Facades\Storage;
class ParseCandidateResume implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=2;public function __construct(public int $resumeId){}public function handle():void{$resume=Resume::with('profile.user')->find($this->resumeId);if(!$resume)return;$resume->update(['parsing_status'=>'processing','parse_error'=>null]);try{$raw=Storage::disk($resume->disk)->get($resume->path);$text=preg_replace('/[^\x20-\x7E\r\n]+/',' ',$raw);preg_match('/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i',$text,$email);preg_match('/(?:\+?91[-\s]?)?[6-9]\d{9}/',$text,$phone);$known=config('recruitment.skills',[]);$skills=collect($known)->filter(fn($skill)=>stripos($text,$skill)!==false)->values()->take(40)->all();$data=['name'=>$resume->profile->user->name,'email'=>$email[0]??$resume->profile->user->email,'phone'=>$phone[0]??$resume->profile->phone,'skills'=>$skills,'experience'=>null,'education'=>null,'companies'=>[]];$resume->update(['parsing_status'=>($email||$phone||$skills)?'processed':'needs_review','parsed_data'=>$data,'parsed_at'=>now()]);}catch(\Throwable $e){$resume->update(['parsing_status'=>'failed','parse_error'=>substr($e->getMessage(),0,2000)]);throw $e;}}}
